BANNER = (
    "> Generated by `tools/` from the inputs in `source/`. Every statement below "
    "is backed by assembly metadata, IL, or a supplied export sample.\n"
    "> Anything that could not be proven from those inputs is marked "
    "**Unknown** rather than guessed.\n")


def _j(obj):
    return json.dumps(obj, indent=2, ensure_ascii=False, sort_keys=True) + "\n"


def _jl(records):
    """Valid JSON array with one record per line.

    Bulk indexes run to hundreds of thousands of rows, where `indent=2` costs
    several times the payload. One compact record per line keeps the file both
    small and line-diffable: a changed method shows up as one changed line
    rather than a reflowed block (spec section 54).
    """
    if not records:
        return "[]\n"
    lines = [json.dumps(r, ensure_ascii=False, sort_keys=True,
                        separators=(",", ":")) for r in records]
    return "[\n" + ",\n".join(lines) + "\n]\n"


def _is_barsa(record_assembly):
    """Barsa domain code: owned by Barsa and not a rebranded library suite."""
    from .inventory import is_barsa_domain
    return is_barsa_domain(record_assembly)


def _write(root, rel, text):
    path = os.path.join(root, rel)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(text)


def _table(headers, rows):
    out = ["| " + " | ".join(headers) + " |",
           "|" + "|".join(["---"] * len(headers)) + "|"]
    for r in rows:
        cells = [str(c).replace("|", "\\|").replace("\n", " ") for c in r]
        out.append("| " + " | ".join(cells) + " |")
    return "\n".join(out)


def _yn(b):
    return "yes" if b else "no"


