def _legacy_table_variance(x, d, cmp_):
    lines = [f"""# Legacy DataSet: cross-sample variance

{BANNER}
One section per table family, with the Barsa type it corresponds to and the
importer path that consumes it. Confidence is per row.

## Multi-sample comparison

Per spec section 17, no table is called optional on one sample's evidence.

{_table(["Metric", "Value"], [
 ["Samples compared", cmp_.get("sampleCount", 0)],
 ["Tables present in every sample", len(cmp_.get("alwaysPresentTables", []))],
 ["Tables present in only some samples", len(cmp_.get("variantTables", []))],
])}

### Always present

{", ".join("`%s`" % t for t in cmp_.get("alwaysPresentTables", [])) or "_none_"}

### Variant (present in some samples only)

These are **not** proven optional. With two samples from one source database,
a table missing from one sample most likely means that system does not use the
feature.

{", ".join("`%s`" % t for t in cmp_.get("variantTables", [])) or "_none_"}

## Columns that vary across samples for a shared table
"""]
    varying = {t: v for t, v in cmp_.get("perTable", {}).items()
               if v["variantColumns"]}
    if varying:
        lines.append(_table(["Table", "Always-present columns", "Variant columns"],
                            [[t, len(v["alwaysPresentColumns"]),
                              ", ".join("`%s`" % c for c in v["variantColumns"])]
                             for t, v in sorted(varying.items())]))
    else:
        lines.append("_No shared table changes its column set between samples._")

    lines.append("\n## Per-table catalogue\n")
    consumer = {
        "MET_METASYSTEM": ("Barsa.Meta.MetaSystem", "NewImportManager::Import"),
        "MET_TYPEDEF": ("Barsa.Meta.TypeDef", "FixIdForImport::FixLocalIds"),
        "MET_FIELDDEF": ("Barsa.Meta.FieldDef", "FixIdForImport::FixLocalIds"),
        "MET_RELATIONDEF": ("Barsa.Meta.RelationDef", "NewImportManager::Import"),
        "met_Relation": ("Barsa.Meta.Relation", "ObjectReferenceBuilder::RecreateForAll"),
        "met_Report": ("Barsa.Meta.Report", "NewImportManager::Import"),
        "MET_FOLDER": ("Barsa.Meta.Folder", "ObjectReferenceBuilder::FixParentCategory"),
        "MET_METACODE": ("Barsa.Meta.MetaCode", "NewImportManager::Import"),
        "MET_METACOMMAND": ("Barsa.Meta.MetaCommand", "NewImportManager::Import"),
        "$IdEmbeddingFields": ("(control table)", "FixIdForImport::FixAll"),
        "$spl_EorgType": ("Barsa.Spl.BasicInfo.EorgType",
                          "FixIdForImport::GetEorgTypeBySourceTypeId"),
        "$Selection": ("Barsa.Spl.BasicInfo.ExportSession",
                       "ImportHelper::ImportionSelectionObjectIdCondition"),
    }
    all_tables = {}
    for p in x.packages:
        for t, info in p.tables.items():
            all_tables.setdefault(t, info)
    rows = []
    for t in sorted(all_tables):
        bt, cons = consumer.get(t, ("Unknown", "Unknown"))
        conf = "CrossVerified" if t in consumer else (
            "Verified" if not t.startswith("$") else "Observed")
        total = sum(p.row_counts.get(t, 0) for p in x.packages)
        rows.append([f"`$.{t}[*]`", len(all_tables[t]["columns"]), total,
                     f"`{bt}`" if bt != "Unknown" else "Unknown",
                     f"`{cons}`" if cons != "Unknown" else "Unknown", conf])
    lines.append(_table(
        ["Path", "Columns", "Rows (all samples)", "Barsa type",
         "Importer consumer", "Confidence"], rows))
    lines.append("""
`Unknown` in the Barsa type or consumer column means no evidence tied that table
to a named type or import step. It does not mean the table is unused.
""")
    _write(d, "formats/legacy-dataset-variance.md", "\n".join(lines) + "\n")


