def _exchange_doc(x, direction):
    is_export = direction == "export"
    label = "Exporter" if is_export else "Importer"
    anti = "importer" if is_export else "exporter"
    types = sorted({t["fullName"] for t in x.types
                    if "DataExchange" in t["fullName"]
                    and direction in t["fullName"].lower()
                    and not t["obfuscatedName"]})
    meths = sorted({"%s::%s" % (m["declaringType"], m["name"])
                    for m in x.methods
                    if "DataExchange" in m["declaringType"]
                    and direction in m["name"].lower()
                    and not m["obfuscatedName"]})
    return f"""# {label} observations

{BANNER}
## Source availability

No `source/{direction}er/` directory was supplied, so there is no first-party
source or decompiled code for the {direction}er. Everything below is read from
`Barsa.Meta.DataExchange.dll` metadata and IL.

This matters: it caps the {direction}er findings at **Observed** for behaviour,
even where the API surface itself is **Verified**.

## Types

{chr(10).join("- `%s`" % t for t in types) if types else "_none_"}

## Methods

{chr(10).join("- `%s`" % m for m in meths[:80]) if meths else "_none_"}

## Obfuscation

Private and internal members of this assembly are renamed. The public surface
above is complete and real; the internals behind it are opaque. Any claim about
*how* a step works internally would be a guess, and is therefore recorded as
Unknown.

## Symmetry with the {anti}

See `evidence/cross-validation.md` and `scenarios/{direction}-system-legacy.md`.
"""


# --- indexes ----------------------------------------------------------------

def _indexes(x, d):
    _write(d, "index/assemblies.json", _j(sorted(
        ({k: v for k, v in r.items() if not k.startswith("_") and k != "key"}
         for r in x.assemblies.values()),
        key=lambda r: (r["assemblyName"], r["path"]))))

    # Scope the bulk indexes to Barsa *domain* code. Indexing every Aspose,
    # DevExpress and Stimulsoft type -- or every control in the Barsa-branded
    # reskins of those suites -- would multiply the pack's size without saying
    # anything about how Barsa models or exchanges a system. Every assembly
    # still appears in assemblies.json with its full counts, so nothing looks
    # silently dropped.
    barsa_types = sorted((t for t in x.types if _is_barsa(t["assembly"])),
                         key=lambda t: (t["assembly"], t["fullName"]))
    _write(d, "index/types.json", _jl(
        [{k: v for k, v in t.items() if not k.startswith("_")}
         for t in barsa_types]))

    # Property and event accessors are reachable through properties.json, and
    # obfuscated members carry no recoverable meaning, so neither earns a row.
    accessor = ("get_", "set_", "add_", "remove_")
    methods = sorted(
        (m for m in x.methods
         if _is_barsa(m["assembly"])
         and not m["obfuscatedName"]
         and not m["name"].startswith(accessor)),
        key=lambda m: (m["assembly"], m["declaringType"], m["name"]))
    _write(d, "index/methods.json", _jl(
        [{k: v for k, v in m.items() if not k.startswith("_")}
         for m in methods]))

    props = []
    for t in barsa_types:
        for prop in t["properties"]:
            props.append({"assembly": t["assembly"],
                          "declaringType": t["fullName"], "name": prop})
    _write(d, "index/properties.json", _jl(sorted(
        props, key=lambda r: (r["assembly"], r["declaringType"], r["name"]))))

    _write(d, "index/fields.json", _jl(sorted(
        [{"assembly": t["assembly"], "declaringType": t["fullName"],
          "fieldCount": t["fieldCount"]}
         for t in barsa_types if t["fieldCount"]],
        key=lambda r: (r["assembly"], r["declaringType"]))))

    # Call edges are kept where both ends are Barsa: an edge into
    # System.String::Concat is noise, an edge into another Barsa type is the
    # evidence this pack is built on.
    edges = []
    for caller in sorted(x.calls):
        owner = x.call_assembly.get(caller, "")
        if owner and not _is_barsa(x.assemblies[owner]["assemblyName"]
                                  if owner in x.assemblies else owner):
            continue
        callees = sorted({c for c in x.calls[caller] if "Barsa" in c})
        if callees:
            edges.append({"caller": caller, "callees": callees})
    _write(d, "index/references.json", _jl(edges))

    _write(d, "index/capabilities.json", _j(x.capabilities))

    _write(d, "index/config-keys.json", _j({
        "status": "Observed",
        "note": ("Call sites are known; key names are assembled at runtime and "
                 "are Unknown."),
        "callSites": sorted(set(sum(x.config_keys.values(), []))),
        "configFiles": sorted(e["path"] for e in x.inputs
                              if e["kind"] == "Config"),
    }))

    _write(d, "index/sql-fragments.json", _j(sorted(
        x.sql, key=lambda s: (s["assembly"], s["method"], s["sql"]))))

    tables = {}
    for s in x.sql:
        for t in s["tables"]:
            tables.setdefault(t, set()).add(s["assembly"])
    export_tables = set()
    for p in x.packages:
        export_tables.update(p.tables)
    _write(d, "index/tables.json", _j(sorted(
        [{"table": t, "assemblies": sorted(a),
          "inExportSample": t in export_tables,
          "confidence": "CrossVerified" if t in export_tables else "Verified"}
         for t, a in tables.items()]
        + [{"table": t, "assemblies": [], "inExportSample": True,
            "confidence": "Verified"}
           for t in export_tables if t not in tables],
        key=lambda r: r["table"])))

    _write(d, "index/export-fields.json", _j({
        "samples": [p.summary() for p in x.packages],
        "comparison": x.package_comparison,
        "idReferenceModel": x.id_model,
        "tables": sorted(
            [{"table": t,
              "columns": info["columns"],
              "isControlTable": info["isControl"],
              "rowsPerSample": {p.path.split("/")[-1]: p.row_counts.get(t, 0)
                                for p in x.packages}}
             for p in x.packages for t, info in p.tables.items()],
            key=lambda r: r["table"]),
    }))

    _write(d, "index/import-actions.json", _j(_import_actions(x)))

    _write(d, "index/normalized-model.json", _j({
        "schemaVersion": "2.0",
        "collections": x.normalized,
        "reconstructionOrder": x.reconstruction_order,
    }))

    chunks = _chunks(x)
    _write(d, "index/knowledge-index.json", _j({
        "schemaVersion": "2.0",
        "generated": time.strftime("%Y-%m-%d"),
        "confidenceOrder": ev.CONFIDENCE_ORDER,
        "scope": {
            "note": ("Bulk indexes (types, methods, properties, fields, "
                     "references) cover Barsa-owned assemblies only. "
                     "Third-party assemblies are inventoried in "
                     "assemblies.json with full counts but not indexed "
                     "member-by-member."),
            "typesIndexed": len(barsa_types),
            "typesSeenOverall": len(x.types),
            "methodsIndexed": len(methods),
            "methodsSeenOverall": len(x.methods),
            "callEdgesKept": len(edges),
        },
        "counts": {
            "assemblies": len(x.assemblies),
            "exportPackages": len(x.packages),
            "capabilities": len(x.capabilities),
            "evidenceItems": len(x.ledger.all()),
            "chunks": len(chunks),
        },
        "inputHashes": sorted(
            [{"path": r["path"], "sha256": r["sha256"],
              "mvid": r["moduleVersionId"], "version": r["assemblyVersion"]}
             for r in x.assemblies.values()]
            + [{"path": p.path, "sha256": p.sha256, "mvid": None,
                "version": p.header.get("Core Version")} for p in x.packages],
            key=lambda r: r["path"]),
        "chunks": chunks,
    }))

    _write(d, "index/evidence.json", _j(x.ledger.all()))


