# --- per-assembly and per-type docs ----------------------------------------

def _assemblies(x, d):
    for key, rec in sorted(x.assemblies.items()):
        if rec.get("_priority", 0) < 50:
            continue
        name = rec["assemblyName"]
        types = sorted((t for t in x.types if t["assemblyKey"] == key),
                       key=lambda t: t["fullName"])
        public = [t for t in types if t["visibility"] == "public"
                  and not t["obfuscatedName"]]
        ns = {}
        for t in types:
            ns[t["namespace"]] = ns.get(t["namespace"], 0) + 1
        safe = rec["fileName"].replace("/", "_")
        _write(d, "assemblies/%s.md" % safe, f"""# Assembly: `{name}`

{BANNER}
{_table(["Property", "Value"], [
 ["File", "`%s`" % rec["fileName"]],
 ["Assembly version", rec["assemblyVersion"]],
 ["Culture", rec["culture"]],
 ["Public key token", rec["publicKeyToken"] or "_unsigned_"],
 ["Target framework", rec["targetFramework"] or "_not declared_"],
 ["Runtime version", rec["runtimeVersion"]],
 ["Architecture", rec["architecture"]],
 ["Module version id", rec["moduleVersionId"]],
 ["SHA-256", rec["sha256"]],
 ["Size", rec["size"]],
 ["Executable", _yn(rec["isExecutable"])],
 ["Types", rec["typesCount"]],
 ["Methods", rec["methodsCount"]],
 ["Fields", rec["fieldsCount"]],
 ["Properties", rec["propertiesCount"]],
 ["Embedded resources", rec["resourcesCount"]],
 ["Obfuscated type names", rec.get("obfuscatedTypeNames", 0)],
])}

## Namespaces

{_table(["Namespace", "Types"],
        sorted(((k or "_(global)_", v) for k, v in ns.items()),
               key=lambda kv: -kv[1])[:30])}

## Referenced assemblies

{", ".join("`%s`" % r for r in rec["referencedAssemblies"]) or "_none_"}

## Public types ({len(public)})

{chr(10).join("- `%s`" % t["fullName"] for t in public[:250])
 if public else "_none_"}
{"" if len(public) <= 250 else chr(10) + "_… %d more; see `index/types.json`._" % (len(public) - 250)}
""")


def _types(x, d):
    """Full markdown for the types this pack's analysis actually rests on."""
    focus = {
        "Barsa.Meta.DataExchange.BixHelper",
        "Barsa.Meta.DataExchange.NewExportManager",
        "Barsa.Meta.DataExchange.NewImportManager",
        "Barsa.Meta.DataExchange.ImportOptions",
        "Barsa.Meta.DataExchange.ObjectReferenceSelection",
        "Barsa.Meta.DataExchange.Helpers.FixIdForImport",
        "Barsa.Meta.DataExchange.Helpers.ImportCloneManager",
        "Barsa.Meta.DataExchange.Helpers.ImportHelper",
        "Barsa.Meta.DataExchange.ImportManager_Structure",
        "Barsa.Meta.DataExchange.ObjectReferenceBuilder",
        "Barsa.Meta.DataExchange.SerializationHelper2",
        "Barsa.Meta.DataExchange.ExportFileNameHelper",
        "Barsa.Meta.DataExchange.ExportSessionHelper",
        "Barsa.Meta.DataExchange.ExportDataSource",
        "Barsa.Meta.DataExchange.ExportSaveContext",
        "Barsa.Meta.DataExchange.MieImportManager",
        "Barsa.Meta.DataExchange.MieExportManagerAll",
        "Barsa.Meta.DataExchange.MissedReferenceFinder",
        "Barsa.Meta.DataExchange.ImportSimulator",
        "Barsa.Meta.DataExchange.SimpleExportSelection",
        "Barsa.Meta.DataExchange.DefaultSystemImportHelper",
        "Barsa.Meta.Extra.Ui.Win.ApplicationExportForm",
        "Barsa.Meta.Extra.Ui.Win.ApplicationImportForm",
        "Barsa.Meta.Extra.Ui.Win.ImportTreeForm",
        "Barsa.Meta.Extra.Ui.Win.Editor.ImportTreeControl",
    }
    by_name = {t["fullName"]: t for t in x.types}
    for fn in sorted(focus):
        t = by_name.get(fn)
        if not t:
            continue
        meths = sorted((m for m in x.methods if m["declaringType"] == fn),
                       key=lambda m: (m["obfuscatedName"], m["name"]))
        visible = [m for m in meths if not m["obfuscatedName"]]
        hidden = [m for m in meths if m["obfuscatedName"]]
        rows = []
        for m in visible:
            sig = "%s%s %s(%s)" % (
                "static " if m["static"] else "",
                m["returnType"] or "?", m["name"],
                ", ".join(m["parameters"] or []))
            key = "%s::%s" % (fn, m["name"])
            callees = [c for c in x.calls.get(key, []) if "Barsa" in c][:6]
            rows.append([m["visibility"], "`%s`" % sig,
                         ", ".join("`%s`" % c.split("::")[-1] for c in callees) or "—"])
        safe = fn.replace("+", "_").replace("/", "_")
        _write(d, "types/%s.md" % safe, f"""# Type: `{fn}`

{BANNER}
{_table(["Property", "Value"], [
 ["Assembly", "`%s`" % t["assembly"]],
 ["Namespace", "`%s`" % (t["namespace"] or "_(global)_")],
 ["Visibility", t["visibility"]],
 ["Base type", "`%s`" % t["baseType"] if t["baseType"] else "—"],
 ["Interfaces", ", ".join("`%s`" % i for i in t["interfaces"]) or "—"],
 ["Methods", t["methodCount"]],
 ["Fields", t["fieldCount"]],
 ["Obfuscated name", _yn(t["obfuscatedName"])],
])}

## Properties

{", ".join("`%s`" % p for p in sorted(t["properties"])) or "_none_"}

## Methods

{_table(["Visibility", "Signature", "Notable Barsa callees"], rows)
 if rows else "_No non-obfuscated methods._"}

{"## Obfuscated members" + chr(10) + chr(10) +
 "%d member names in this type were renamed by the obfuscator and carry no "
 "recoverable meaning: %s" % (len(hidden), ", ".join("`%s`" % m["name"] for m in hidden[:30]))
 if hidden else ""}

## Confidence

Signatures above are **Verified** — read from the MethodDef table and signature
blobs. Callee lists are **Observed** — resolved from IL call operands, in opcode
order, which is not necessarily execution order.
""")
